INSERT INTO videos (video_id, channel_id, title, published_at, duration_seconds, description, thumbnail_url, video_url) VALUES ('o3fMDF3PGhM', 'UCUEOHBht8pnQhQvCfIcl-gg', '2. Crear Tabla Calendario en Power BI [Es más sencillo que Power Query]', '2023-08-10 06:51:18+00:00', 1718, 'Descarga de Archivo: https://drive.google.com/drive/folders/1w41Ka4vgTT46tNDuMlNLU4n0OosLNDD0?usp=sharing

--Dax:

ADDCOLUMNS(
    CALENDAR(
            DATE(YEAR(MIN(Sales[DateKey])), 1, 1),  
            DATE(YEAR(MAX(Sales[DateKey])), 12, 31)
            ),
           "Año NRO",year([Date]),
           "Mes NRO",MONTH([Date]),
           "Día NRO",DAY([Date]),
           "Día del año NRO", DATEDIFF(DATE(YEAR([Date]), 1, 1), [Date], DAY) + 1,
           "Día de semana NRO",WEEKDAY([Date],2),
           "Día de semana TXT",FORMAT([Date],"DDDD"),
           "Mes TXT",FORMAT([Date],"MMMM"),
           "Trimestre",ROUNDUP(MONTH([Date])/3,0)
)


--Se ha agregado la expresión DATE y YEAR para obtener las fechas completas del año, es decir desde 01 de enero hasta el 31 de diciembre, según la columna Ventas[Fecha del pedido]
--Se ha agregado la columna "Día del año NRO" que contiene una cuenta del 1 al 365 día del año.', 'https://i.ytimg.com/vi/o3fMDF3PGhM/hqdefault.jpg', 'https://www.youtube.com/watch?v=o3fMDF3PGhM')
